// Native adaptation of https://hyperframes.heygen.com/catalog/components/x-follow-card (Apache-2.0).
// Copyright 2026 HeyGen, Inc. Changes: original editable profile, generated images and native Follow interaction.
export default defineSpanScene({
  id: "x-follow-card", width: 1920, height: 1080, durationMs: 5000, editPreviewMs: 2000,
  variables: {
    width: numberVar(1920), height: numberVar(1080), creator: stringVar("Elias Reed"),
    handle: stringVar("@eliasframes"), stat: stringVar("18.6K followers"),
    bio: stringVar("Short films, quiet details. Sharing my latest Mont edits."),
    avatarSrc: stringVar("data:image/png;base64,"), heroSrc: stringVar("data:image/png;base64,"),
    mayaSrc: stringVar("data:image/png;base64,"), theoSrc: stringVar("data:image/png;base64,"), niaSrc: stringVar("data:image/png;base64,"),
    soraSrc: stringVar("data:image/png;base64,"), julesSrc: stringVar("data:image/png;base64,"), avaSrc: stringVar("data:image/png;base64,"),
    actionLabel: stringVar("Follow"), confirmedLabel: stringVar("Following"),
    background: colorVar("#FAFAFA"), surface: colorVar("#090B0E"), foreground: colorVar("#FFFFFF"),
    muted: colorVar("#8B98A5"), revealAtMs: numberVar(500), pressAtMs: numberVar(1600),
  },
  computeds: {
    scale: computed.number(() => Math.min(vars.width / 1920, vars.height / 1080)),
    clock: computed.number(() => time.loop(5000) * 5000),
    statProgress: computed.number(() => Math.max(0, Math.min(1, (computed.clock - vars.revealAtMs) / 460))),
    statEase: computed.number(() => 1 + 2.6 * Math.pow(computed.statProgress - 1, 3) + 1.6 * Math.pow(computed.statProgress - 1, 2)),
    press: computed.number(() => Math.max(0, Math.min(1, (computed.clock - vars.pressAtMs) / 80))),
    release: computed.number(() => Math.max(0, Math.min(1, (computed.clock - vars.pressAtMs - 80) / 160))),
    buttonScale: computed.number(() => computed.clock < vars.pressAtMs + 80 ? 1 - 0.05 * Math.pow(computed.press, 3) : 0.95 + 0.05 * (1 - Math.pow(1 - computed.release, 3))),
    oldLabel: computed.number(() => 1 - Math.max(0, Math.min(1, (computed.clock - vars.pressAtMs - 80) / 80))),
    newLabel: computed.number(() => Math.max(0, Math.min(1, (computed.clock - vars.pressAtMs - 80) / 160))),
    colorSwap: computed.number(() => Math.max(0, Math.min(1, (computed.clock - vars.pressAtMs - 80) / 120))),
    particle: computed.number(() => Math.max(0, Math.min(1, (computed.clock - vars.pressAtMs - 80) / 480))),
    particleEase: computed.number(() => 1 - Math.pow(1 - computed.particle, 3)),
    ring: computed.number(() => Math.max(0, Math.min(1, (computed.clock - vars.pressAtMs - 80) / 280))),
  },
  render({vars, computed}) {
    return <Scene width={vars.width} height={vars.height}>
      <Rect id="background" width={vars.width} height={vars.height} fill={vars.background} />
      <Repeat items={[vars.avatarSrc, vars.heroSrc, vars.mayaSrc, vars.theoSrc, vars.niaSrc, vars.soraSrc, vars.julesSrc, vars.avaSrc]} render={(src,index) => <Image id={"resource-prewarm-"+index} src={src} x={-4096} y={-4096} width={1} height={1} borderWidth={0} borderColor="transparent" />} />
      <Group id="frame" x={(vars.width - 1920 * computed.scale) / 2} y={(vars.height - 1080 * computed.scale) / 2} width={0} height={0} pivotX={0} pivotY={0} scaleX={computed.scale} scaleY={computed.scale}>
        <Group id="follower-card" x={576} y={284} width={0} height={0} pivotX={0} pivotY={0}>
          <Rect id="card" width={768} height={512} radius={30} fill={vars.surface} shadowColor="#0F172A" shadowBlur={40} shadowOffsetY={28} shadowOpacity={0.1} />
          <Image id="profile-hero" src={vars.heroSrc} width={768} height={160} borderWidth={0} borderColor="transparent" />
          <Ellipse id="avatar-ring" x={28} y={108} width={108} height={108} fill={vars.surface} />
          <Image id="creator-avatar" src={vars.avatarSrc} x={34} y={114} width={96} height={96} borderWidth={0} borderColor="transparent" />
          <Text id="creator-name" text={vars.creator} x={34} y={224} width={520} height={43} fontFamily="Inter" fontWeight={700} size={34} lineHeight={1.2} letterSpacing={-0.7} fit="none" color={vars.foreground} />
          <Text id="creator-handle" text={vars.handle} x={34} y={269} width={520} height={24} fontFamily="Inter" fontWeight={400} size={19} lineHeight={1.2} fit="none" color={vars.muted} />
          <Text id="profile-bio" text={vars.bio} x={34} y={310} width={700} height={28} fontFamily="Inter" fontWeight={400} size={20} lineHeight={1.3} fit="none" color={vars.foreground} />
          <Text id="follower-stat" text={vars.stat} x={34} y={351 + 28 * (1 - computed.statEase)} width={700} height={51} fontFamily="Inter" fontWeight={700} size={38} lineHeight={1.3} letterSpacing={-1.2} fit="none" color={vars.foreground} opacity={Math.max(0, Math.min(1, computed.statEase))} />
          <Repeat items={[vars.mayaSrc,vars.theoSrc,vars.niaSrc,vars.soraSrc,vars.julesSrc,vars.avaSrc]} render={(src,index) => (
            <Group id={"follower-" + index} x={24 + index * 42} y={422 + 18 * Math.pow(1 - Math.max(0, Math.min(1, (computed.clock - vars.revealAtMs - 220 - index * 50) / 280)), 3)} width={0} height={0} pivotX={0} pivotY={0} opacity={1 - Math.pow(1 - Math.max(0, Math.min(1, (computed.clock - vars.revealAtMs - 220 - index * 50) / 280)), 3)}>
              <Ellipse id={"follower-ring-" + index} width={52} height={52} fill={vars.surface} />
              <Image id={"follower-photo-" + index} src={src} x={3} y={3} width={46} height={46} borderWidth={0} borderColor="transparent" />
            </Group>
          )} />
          <Group id="button" x={622} y={207} width={0} height={0} pivotX={0} pivotY={0} scaleX={computed.buttonScale} scaleY={computed.buttonScale}>
          <Rect id="activation-ring" x={-88 * (1 + 0.4 * computed.ring)} y={-26 * (1 + 0.7 * computed.ring)} width={176 * (1 + 0.4 * computed.ring)} height={52 * (1 + 0.7 * computed.ring)} radius={26 * (1 + 0.7 * computed.ring)} fill="transparent" stroke="#FF642B" strokeWidth={2} opacity={computed.clock >= vars.pressAtMs + 80 ? 0.6 * (1 - computed.ring) : 0} />
          <Repeat items={[0.12, 0.81, 1.57, 2.42, 3.08, 3.94, 4.71, 5.52, 6.0]} render={(angle,index) => (
            <Ellipse id={"activation-particle-" + index} x={Math.cos(angle) * (88 + 42 + (index % 3) * 11) * computed.particleEase - 3} y={Math.sin(angle) * (26 + 38 + (index % 4) * 8) * computed.particleEase - 3} width={4 + index % 3} height={4 + index % 3} fill="#FF642B" opacity={computed.clock >= vars.pressAtMs + 80 && computed.particle < 1 ? 1 - computed.particle * computed.particle : 0} />
          )} />
            <Rect id="button-before" x={-88} y={-26} width={176} height={52} radius={26} fill="#FFFFFF" />
            <Rect id="button-after" x={-88} y={-26} width={176} height={52} radius={26} fill="#252C33" opacity={computed.colorSwap} />
            <Text id="action-label" text={vars.actionLabel} x={-88} y={-14} width={176} height={28} fontFamily="Inter" fontWeight={700} size={22} lineHeight={1.2} fit="none" color="#0F1419" align="center" opacity={computed.oldLabel} />
            <Text id="confirmed-label" text={vars.confirmedLabel} x={-88} y={-14} width={176} height={28} fontFamily="Inter" fontWeight={700} size={22} lineHeight={1.2} fit="none" color="#FFFFFF" align="center" opacity={computed.newLabel} />
          </Group>
        </Group>
      </Group>
    </Scene>;
  },
});
